def find_district_for_client(gender, birth_date):
    filtered_clients = client[(client['gender'] == gender) & (client['birth_date'] == birth_date)]
    if not filtered_clients.empty:
        district_id = filtered_clients.iloc[0]['district_id']
        district_info = district[district['district_id'] == district_id]
        if not district_info.empty:
            return district_info.iloc[0].tolist()
    return None

# Example usage
result = find_district_for_client('Female', '1976-01-29')
print(result)
