```python
def calculate_female_proportion(prague_branch_accounts):
    prague_branch_accounts = prague_branch_accounts.merge(
        district[['district_id', 'A1']], 
        left_on='district_id', 
        right_on='district_id'
    )
    prague_branch_accounts['female_proportion'] = prague_branch_accounts.apply(
        lambda row: (row['gender'] == 'F') / len(row['client_id']), 
        axis=1
    )
    return prague_branch_accounts['female_proportion'].mean()
```
